package com.propertyapp.storage;

import java.util.Optional;

/**
 * Where uploaded images live (ADR-0016). Callers store and read by key, such as
 * {@code images/3f2c….jpg}; only {@link #publicUrl(String)} knows the host, so the vendor or CDN
 * can change without touching stored data.
 */
public interface StorageService {

    /** Writes the object. Keys are generated by the app and never reuse a name. */
    void put(String key, byte[] bytes, String contentType);

    /** The object's bytes, or empty when there is none. */
    Optional<byte[]> get(String key);

    boolean exists(String key);

    void delete(String key);

    /** The address browsers load the object from. */
    String publicUrl(String key);

    /** Short name for logs and health: "local" or "s3". */
    String kind();
}
